INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-17-youtube-skills-vs-mcp-agent-tooling-intake#4', '2026-05-17-youtube-skills-vs-mcp-agent-tooling-intake', 4, 'Initial questions',
  '## Initial questions

- Should Techscope prefer skills over MCP for local coding-agent workflows?
- Which MCP categories can be safely replaced by skills or local scripts?
- Which integrations still deserve MCP because they need OAuth, centralization, caching, shared governance or remote API-agent support?
- Should this become a draft standard for future agent configuration?', 'a70b1a15cf3595360583662506ba6a73ce6954786e0e5084f992945202c506c6', 76
);
