INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-17-hermes-agent-source-note#2', '2026-05-17-hermes-agent-source-note', 2, 'Source snapshot',
  '## Source snapshot

