INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-18-hermes-agent-practical-use-cases-source-note#8', '2026-05-18-hermes-agent-practical-use-cases-source-note', 8, 'Risks',
  '## Risks

- Many examples involve sensitive personal or business data: travel documents, bank statements, CRM-like data, Telegram channels, meeting recordings and personal images.
- Role agents can silently accumulate stale skills and bad memory if skill creation is not reviewed.
- Telegram control can become noisy or unsafe without allowlists, concise responses, permission gates and audit logs.
- Codex CLI bridge work needs workspace isolation, sandboxing and clear completion criteria.', '8c7c90ee6c3fa99507b36994f193f0c44ebb766d8b8788136e8f92de6d72487a', 96
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Risks

