INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-17-medium-harness-engineering-six-layer-signal#7', '2026-05-17-medium-harness-engineering-six-layer-signal', 7, 'Verification required',
  '## Verification required

- Verify exact article URL if needed; this pass only found Medium list/activity confirmations.
- Do not accept `Context Anxiety`/`Context Reflect` labels as Anthropic-official without a primary source using those exact terms.
- Compare the six-layer model against OpenAI and Anthropic primary sources before promoting it to an active standard.
- Run a local Techscope harness-layer audit to test whether the model exposes real gaps.', '15753bd6aae65872957d872315dd8e5de75ba9b019729faa0a0bde1bbff38089', 92
);
