INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-15-harness-engineering-codex-agents-brief', '02_briefs/2026-05-15-harness-engineering-codex-agents-brief.md', 'brief', 'draft', 'Brief: harness-engineering-codex-agents',
  'Ryan Lopopolo описывает harness engineering как инженерную дисциплину вокруг coding agents: человек больше не должен быть главным производителем кода, а должен проектировать среду, инструкции, guardrails, CI feedback loops, review agents, repo structure и проверяемые acceptance criteria, чтобы агенты могли выполнять полный цикл разработки. Главный сдвиг: implementation становится дешевой и параллелизуемой, а дефицитными ресурсами становятся human time, human/model attention и context window.', 'ebf8af88238c68130b5aad79e935e9f04c81db82ba8a3874446368517ab97561', '2026-05-15', '2026-05-15', '2026-05-30T00:26:15.344Z'
)
