INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-15-youtube-local-transcription-test-brief', '02_briefs/2026-05-15-youtube-local-transcription-test-brief.md', 'brief', 'draft', 'Brief: youtube-local-transcription-test',
  'Локальная транскрибация YouTube-видео сработала. У ролика не было доступных субтитров или автосубтитров через `yt-dlp`, поэтому был использован полноценный путь: ```text YouTube URL -> yt-dlp mp4 download -> ffmpeg audio extraction -> mlx-whisper ASR -> JSON transcript ``` Результат пригоден как подтверждение, что на Mac можно собрать рабочий локальный pipeline без AI Studio и без ручной загрузки аудио в веб-интерфейс.', '8c3afcbfa9adfb2bfadfde0c67a8f5150a5f02c1691d72bfeb91829c0891b73e', '2026-05-15', '2026-05-15', '2026-05-30T00:26:15.344Z'
)
