INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-16-openai-realtime-audio-models-voice-agents-brief', '02_briefs/2026-05-16-openai-realtime-audio-models-voice-agents-brief.md', 'brief', 'draft', 'Brief: OpenAI realtime audio models for voice agents',
  'OpenAI announced three realtime audio models in the API: `GPT-Realtime-2`, `GPT-Realtime-Translate` and `GPT-Realtime-Whisper`. For Techscope, the most useful idea is not simply higher-quality speech. The agent-design signal is that voice agents can now stay in a live conversation while reasoning, calling tools, translating or transcribing in the background. This creates a new design surface for agents: voice UX, preambles, interruption handling, progress updates, live transcript memory, multilingual support and consent/privacy rules.', '908e9e21584b68f7cf865f15caf9e46c1bb6fd6e2c410b0c8fab0405de0f661f', '2026-05-16', '2026-05-16', '2026-05-30T00:26:15.344Z'
)
