INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-17-claude-code-32-hacks-brief', '02_briefs/2026-05-17-claude-code-32-hacks-brief.md', 'brief', 'draft', 'Brief: Claude Code 32 hacks',
  'The useful signal is not the full list of "32 hacks" as a checklist. The useful signal is a compact operating model for coding agents: keep long-lived context small, plan before editing, bake verification into the task list, use isolated workers for parallel exploration, use worktrees for parallel code changes, prefer narrow tools over broad tool surfaces, and make permissions explicit. For Techscope, this is highly relevant, but mostly as `adapter-needed`: the source is Claude Code-specific, while our primary implementation environment is Codex.', 'cb5cf283de09e8f80b023157456ed76e6832fd1bc65599fc8c22886c25e0bbac', '2026-05-17', '2026-05-17', '2026-05-30T00:26:15.344Z'
