INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-17-cli-vs-mcp-tool-selection-brief', '02_briefs/2026-05-17-cli-vs-mcp-tool-selection-brief.md', 'brief', 'draft', 'Brief: CLI vs MCP tool selection',
  'The video strengthens Techscope''s emerging rule for agent tool design: CLI is the right default when a known command directly maps to a local developer task; MCP is justified when the useful abstraction is not the raw command, but a managed service boundary, rendered output, authentication, per-user permissions, auditability or centralized integration. This is not an "MCP is bad" source. It is a routing source. It says agents should choose the smallest reliable interface for the job.', '4403e1d7210d4845126064c750cb2425e892c871fe3a75d660801b561147d07a', '2026-05-17', '2026-05-17', '2026-05-30T00:26:15.344Z'
)
