INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-17-codex-mobile-desktop-remote-connection-brief', '02_briefs/2026-05-17-codex-mobile-desktop-remote-connection-brief.md', 'brief', 'draft', 'Brief: Codex mobile/desktop remote connection',
  'Скриншот показывает, что мобильный Codex/ChatGPT UI уже работает как поверхность управления подключениями: виден существующий `Codex Desktop` host и форма `Add SSH Host`. В сочетании с официальной статьей OpenAI от 2026-05-14 это подтверждает важный UX-сдвиг: Codex можно использовать не только сидя за рабочей машиной, но и как long-running agent, которым пользователь управляет с телефона.', 'd2bcf7104ce420e4bf246f2e716015ed3db7c91643f6693c8910a6f6b31bcda7', '2026-05-17', '2026-05-17', '2026-05-30T00:26:15.344Z'
)
