INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-17-codex-mobile-local-sessions-brief', '02_briefs/2026-05-17-codex-mobile-local-sessions-brief.md', 'brief', 'draft', 'Brief: Codex mobile access to local sessions',
  'Codex mobile access to local sessions is strategically important for Techscope. It means the user can monitor, steer, approve and continue work running on a laptop, Mac mini, devbox or remote environment from the ChatGPT mobile app. This can reduce the need for custom Telegram bridges for controlling active Codex work. It does not remove the need for our Telegram intake bot. Telegram still solves a different job: capturing posts, links, screenshots and voice/media into the Techscope knowledge base.', '6caf3e7130dcc43a10dd712f4bda1f3a4d8bf1d79721d4615c6142b72ed1b53b', '2026-05-17', '2026-05-17', '2026-05-30T00:26:15.344Z'
)
