INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-17-codex-remote-vps-connections-brief#5', '2026-05-17-codex-remote-vps-connections-brief', 5, 'Risks and caveats',
  '## Risks and caveats

- VPS agents increase blast radius: credentials, repos, secrets, network exposure and persistence.
- Mobile approval can bypass careful review if prompts are unclear.
- Enterprise/workspace controls may differ from consumer setup.', '5a6760f6248328120e99745fd6155cb6504c64e45d7a48f34446278035e30cd1', 49
);
