INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-17-hermes-agent-setup-brief', '02_briefs/2026-05-17-hermes-agent-setup-brief.md', 'brief', 'draft', 'Brief: Hermes Agent setup and Telegram gateway',
  'The video is useful as a hands-on setup walkthrough for Hermes Agent as an always-on personal agent: VPS or Mac mini, Docker/service persistence, provider keys, Telegram bot, gateway pairing and command approvals. It does not replace official docs and should not be treated as proof that Hermes supersedes OpenClaw. For Techscope, the main value is not the Hostinger path itself. The value is the deployment pattern: start with a working CLI agent, add provider configuration, then expose it through a controlled messaging gateway, with persistent storage and explicit authorization.', '7d2f5dd890fc53e7e776ad1a83a21684fda18804ecb2207ad39b0087746ebf7f', '2026-05-17', '2026-05-17', '2026-05-30T00:26:15.344Z'
)
