INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-17-mimiclaw-embedded-agent-brief', '02_briefs/2026-05-17-mimiclaw-embedded-agent-brief.md', 'brief', 'draft', 'Brief: MimiClaw embedded agent architecture',
  'MimiClaw is an OpenClaw-inspired embedded agent that runs the agent control loop on an ESP32-S3 microcontroller instead of a Mac mini, VPS, Linux box or Node/Python runtime. The LLM still runs in the cloud, but the device owns the interaction loop, Telegram/WebSocket channels, memory/session files, tool registry, serial CLI, OTA flow and low-power always-on operation. For Techscope, MimiClaw is valuable as a boundary-case architecture. It shows what survives when an autonomous agent is squeezed into tiny hardware: simple queues, explicit tasks, plain-text memory, narrow tools, constrained config and a very visible security boundary.', '65afeab5bc3d4cc331e04fc54657bb33a7f68456337145272eeedaf2c137534a', '2026-05-17', '2026-05-17', '2026-05-30T00:26:15.344Z'
)
