INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-17-skills-vs-mcp-agent-tooling-brief', '02_briefs/2026-05-17-skills-vs-mcp-agent-tooling-brief.md', 'brief', 'draft', 'Brief: Skills vs MCP for agent tooling',
  'The useful conclusion is not "Skills killed MCP". Skills and MCP solve adjacent but different problems. MCP is a protocol for exposing external context, tools and services to agents. Skills are portable, progressive-disclosure instructions that tell an agent how to perform a task, often by using local scripts, CLIs, reference files or MCP tools. For Techscope and future coding agents, the practical rule should be: prefer skills for local repeatable workflows and process knowledge; prefer MCP for service integration, OAuth, shared governance, caching, remote/API-agent environments and standardized tool access.', 'd0a540a90d0c0932cf79c32489838ec702e36d74362c906950bf3f502803d11e', '2026-05-17', '2026-05-17', '2026-05-30T00:26:15.344Z'
)
