INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-18-hermes-agent-practical-use-cases-brief', '02_briefs/2026-05-18-hermes-agent-practical-use-cases-brief.md', 'brief', 'processed', 'Brief: Hermes practical role-agent system',
  'The video is useful because it shows how an advanced operator turns Hermes into a practical team of role agents: coordinator, designer, marketer, researcher, economist, document helper, planner and Codex CLI bridge. The key lesson for Techscope is not a specific Hermes command, but an agent-product pattern: each agent should own a narrow recurring pain, have its own memory and skills, and communicate through a shared map/wiki plus concise human-facing messages.', '3ea8c973d8aeaba35d8c1a8de395b82d19aa52b54c02d1517c6f7a3e8a56a4da', '2026-05-18', '2026-05-18', '2026-05-30T00:26:15.344Z'
)
