INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-18-hermes-goal-autonomous-workflow-brief', '02_briefs/2026-05-18-hermes-goal-autonomous-workflow-brief.md', 'brief', 'processed', 'Brief: Hermes `/goal` and persistent autonomous workflows',
  'The useful idea in the video is persistent goal execution: a long-running agent loop bound to a measurable objective, monitored by a judge/evaluator, constrained by a budget and controlled with pause/resume/clear plus mid-run subgoals. This is a direct harness-engineering pattern for Techscope and Agents Mother. The noisy parts are the hype, hosting sponsorship, adoption claims and business anecdotes. They should not drive decisions. The architecture signal is still strong because official Hermes docs and Codex release notes confirm the core mechanism.', '5ed3742f2c19a5a07a0664a406f23cea9e2d1608e8e54bd70f7fef90023da874', '2026-05-18', '2026-05-18', '2026-05-30T00:26:15.344Z'
)
