INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  'brief-nvidia-nemoclaw-sandboxed-agent-runtime-2026-05-27', '02_briefs/2026-05-27-nvidia-nemoclaw-sandboxed-agent-runtime-brief.md', 'brief', 'draft', 'Brief: NVIDIA NemoClaw sandboxed agent runtime',
  'NemoClaw is useful to Techscope primarily as a reference architecture for sandboxing always-on agents, not as a default stack to install. The new reusable idea is a strict runtime boundary: host-side operator/control plane, sandboxed agent process, gateway-held credentials, deny-by-default egress, declarative policy presets, lifecycle logs/status and routed inference.', '1be98527498af9edd84f2264c75d94bd7e21be5c4e1918a71d1ec5b8b987c056', '2026-05-27', '2026-05-27', '2026-05-30T00:26:15.344Z'
