INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-15-youtube-conditionals-agent-assessment#5', '2026-05-15-youtube-conditionals-agent-assessment', 5, 'Programming relevance',
  '## Programming relevance

Score: 1/5

