INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-17-skills-vs-mcp-agent-tooling-assessment#17', '2026-05-17-skills-vs-mcp-agent-tooling-assessment', 17, 'Evidence',
  '### Evidence

