INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'realtime-voice-control-for-codex-agents#11', 'realtime-voice-control-for-codex-agents', 11, 'Examples',
  '## Examples

- FESPA26: voice-controlled event/media/reportage agent. Realtime handles operator dialogue; server tools update FESPA memory and feed state; Codex App/CLI handles source search, media analysis, card updates, translation, follow-up checklists and system changes.
- Funny Teacher: voice-controlled learning agent. Realtime handles teaching dialogue; server tools manage lesson memory and outcomes.', '428db514d0d13bfbc5fa6a23b45230136e76b5c541e5fbc411847ae0f72b07dc', 69
);
