INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'signal-extraction#4', 'signal-extraction', 4, 'Keep',
  '## Keep

- технические claims;
- конкретные практики;
- tool/API/model/library names;
- архитектурные ограничения;
- failure modes;
- security/DX risks;
- eval ideas;
- candidate rules for agents;
- primary-source links and verification tasks.', '7b40a9ecea39d0dabff5114b7bd4a3478b91784a92ddf7a2a0fe788e2cda9832', 46
);
