INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'techscope-quality-and-release-roadmap#80', 'techscope-quality-and-release-roadmap', 80, 'Verification gate',
  '### Verification gate

