INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'agents-mother#21', 'agents-mother', 21, 'Non-goals for v1',
  '## Non-goals for v1

- Universal generator for every agent platform.
- Automatic deployment.
- Automatic secret provisioning.
- Copying TechScope internals 1:1 into every new agent.
- Treating Telegram as mandatory.', '0f559f58fb539275434d60e7f77d72b336dd15959a6884a7beaa9b4168425566', 44
);
