INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'llm-wiki-layer#9', 'llm-wiki-layer', 9, 'Promotion rule',
  '## Promotion rule

If a generated wiki page looks strong enough to affect project standards, create a review or decision first. Do not promote generated synthesis directly into `04_standards/`.', 'cecbe150bbecd72d979ebd5fe0eacaeafcd39bceb919afef3fb152afbe2af9ec', 40
);
