INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'telegram-intake-bot#6', 'telegram-intake-bot', 6, 'Bot commands',
  '## Bot commands

- `/help`: show short usage.
- `/queue`: show queue status.
- `/reindex`: run memory validation, SQLite rebuild and local embeddings from Telegram.', 'e8943aaf58cd986be272e884b121cc3daadbb78a9433a4195e706fd2181ab30e', 34
);
