INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-19-fespa26-agent-contract#2', '2026-05-19-fespa26-agent-contract', 2, 'Purpose',
  '## Purpose

- Agent name: FESPA26
- Primary mission: Voice-first Codex CLI agent for processing FESPA 2026 media and building a bilingual live news feed for Durst, Flora, Scodix, PrintFactory and related exhibitors
- Target user: single operator
- Success criteria: user can speak with the agent in Russian or English, upload/link media, have the material saved into local memory, and see generated/curated feed cards in a mobile-first vertical web feed.
- Out of scope: public multi-user deployment, automatic publishing to external social networks, paid ad buying, unattended web scraping at scale, and automatic long-running service/autostart without explicit approval.', '998891cca6d256245d9c6aa1fd2249157bf7bce13963d6c58f7a4d3a16b251cb', 134
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Purpose

- Agent name: FESPA26
- Primary mission: Voice-first Codex CLI agent for processing FESPA 2026 media and building a bilingual live news feed for Durst, Flora, Scodix, PrintFactory and related exhibitors
- Target user: single operator
- Success criteria: user can speak with the agent in Russian or English, upload/link media, have the material saved into local memory, and see generated/curated feed cards in a mobile-first vertical web feed.
- Out of scope: public multi-user deployment, automatic publishing to external social networks, paid ad buying, unattended web scraping at scale, and automatic long-running service/autostart without explicit approval.', 'Purpose', '2026-05-19-fespa26-agent-contract', '2026-05-19-fespa26-agent-contract#2');

