INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-19-fespa26-agent-contract#7', '2026-05-19-fespa26-agent-contract', 7, 'Runtime and interface',
  '## Runtime and interface

- Runtime family: hybrid
- Primary interface: web
- Secondary interfaces: local CLI maintenance scripts
- Telegram mode: none
- Expected hosting: local Mac first; Mac mini service later only after approval', '121a52d758a8636b98828763ddc2eff8c761dc60572eb414264d4492182aa893', 49
);
