INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-19-fespa26-agent-contract#8', '2026-05-19-fespa26-agent-contract', 8, 'Operations and service',
  '## Operations and service

- Deployment target: local Mac
- Deployment profile: local-development
- Service mode: manual
- Autostart: disabled
- Start command: npm run dev
- Stop command: stop the dev server process
- Healthcheck command: npm run test && npm run build
- Log path: logs/
- Restart policy: manual unless contract is updated', '49868633753103e0fe65e660f66806831ae3254a508b4d943ffe0bece98d8fce', 76
);
