INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-19-fespa26-agent-contract#9', '2026-05-19-fespa26-agent-contract', 9, 'Proactivity',
  '## Proactivity

- Proactive mode: manual
- Trigger sources: voice command, UI ingest form, local CLI command
- Schedule: not-applicable
- Heartbeat interval: not-applicable
- Idle behavior: sleep until trigger
- User interruption policy: do not interrupt unless configured by user', 'a1efea700cbb62503031648472752bc5c64b3b3f56bbd255cee00a32e86f0eb7', 56
);
