INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-25-fespa26-agent-contract#14', '2026-05-25-fespa26-agent-contract', 14, 'Scaffold Requirements',
  '## Scaffold Requirements

