INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-25-funny-teacher-agent-contract#7', '2026-05-25-funny-teacher-agent-contract', 7, 'Runtime And Interface',
  '## Runtime And Interface

- Runtime family: hybrid.
- Primary interface: web voice only.
- Secondary interfaces: local CLI maintenance scripts; Codex project for development.
- Telegram mode: none for v1 unless user later requests it.
- Expected hosting: local Mac or Mac mini, with optional Tailscale access.', '376c8d4ae9df522756c516edec8986f4a110143378e631cffabb5a38d4400d73', 65
);
