INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-18-techscope-agent-operations-report#5', '2026-05-18-techscope-agent-operations-report', 5, 'Proactivity',
  '## Proactivity

- Mode: `queue-watcher`
- Trigger sources: Telegram getUpdates polling, manual Codex thread work, local scripts
- Schedule: none
- Heartbeat interval: Telegram long polling timeout 30s
- Idle behavior: Stay resident as launchd service; process queued intake only when messages arrive.', 'edf491c11d562c853eeb45a8ab7aff9be10be4d22541b6e44bc10fc4d2bbbbe3', 59
);
