INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-19-fespa26-agent-scaffold-report#2', '2026-05-19-fespa26-agent-scaffold-report', 2, 'Summary',
  '## Summary

- Project path: `<SIBLING_AGENT_ROOT>/FESPA26`
- Scaffold type: custom Agents Mother scaffold based on the proven `fast_talk` Realtime/Codex architecture.
- Primary interface: Web UI.
- Runtime: `gpt-realtime-2` voice dispatcher plus Codex CLI sidecar.
- Memory: local SQLite operational memory and local uploads under `data/`.
- Deployment: manual local development, no autostart.', '1121e205b9aa9e484f6c99f96adc37df9603f5c489c2fef3cc05ba4588620219', 71
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Summary

- Project path: `<SIBLING_AGENT_ROOT>/FESPA26`
- Scaffold type: custom Agents Mother scaffold based on the proven `fast_talk` Realtime/Codex architecture.
- Primary interface: Web UI.
- Runtime: `gpt-realtime-2` voice dispatcher plus Codex CLI sidecar.
- Memory: local SQLite operational memory and local uploads under `data/`.
- Deployment: manual local development, no autostart.', 'Summary', '2026-05-19-fespa26-agent-scaffold-report', '2026-05-19-fespa26-agent-scaffold-report#2');

INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-19-fespa26-agent-scaffold-report#3', '2026-05-19-fespa26-agent-scaffold-report', 3, 'Created',
  '## Created

- `AGENTS.md`
- `README.md`
- `.env.example`
- Next.js app with `/voice` console.
- FESPA feed UI tab.
- FESPA ingest/feed/media API routes.
- Realtime tool route.
- SQLite migration for `fespa_sources`, `fespa_feed_items`, `fespa_jobs`.
- Layer manifests: interfaces, memory, tools, operations.
- Status scripts and smoke test.', 'a8f8606ec3c9f25e521cb1aeb2faf778ccc8587c39da7fcc816d35f94ab97934', 65
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Created

- `AGENTS.md`
- `README.md`
- `.env.example`
- Next.js app with `/voice` console.
- FESPA feed UI tab.
- FESPA ingest/feed/media API routes.
- Realtime tool route.
- SQLite migration for `fespa_sources`, `fespa_feed_items`, `fespa_jobs`.
- Layer manifests: interfaces, memory, tools, operations.
- Status scripts and smoke test.', 'Created', '2026-05-19-fespa26-agent-scaffold-report', '2026-05-19-fespa26-agent-scaffold-report#3');

INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-19-fespa26-agent-scaffold-report#4', '2026-05-19-fespa26-agent-scaffold-report', 4, 'Verification',
  '## Verification

- `npm run smoke`: pass.
- `npm run lint`: pass.
- `npm test`: pass, 39 tests.
- `npm run build`: pass.
- Browser check: `/voice` opens, `FESPA26` title visible, Feed tab renders empty mobile feed state.
- API check: `/api/health` and `/api/fespa/feed` respond.', '3a67c740029798d9114fe3d2a6a2703acfcbcdaf70d4666ff01158f57eab08a0', 61
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Verification

