INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-26-funny-teacher-agent-user-interaction-review#1', '2026-05-26-funny-teacher-agent-user-interaction-review', 1, 'Agent User Interaction Review: Funny Teacher',
  '# Agent User Interaction Review: Funny Teacher

Date: 2026-05-26
