INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-28-techscope-quality-phase-13-github-ci-release-prep-report#9', '2026-05-28-techscope-quality-phase-13-github-ci-release-prep-report', 9, 'AM-CANDIDATE patterns',
  '## AM-CANDIDATE patterns

- `github-quality-workflow`: GitHub Actions quality gate with Node matrix.
- `markdown-validate-workflow`: focused source-of-truth validation workflow.
- `setup-wizard-ci-smoke`: clean temp setup smoke in CI.
- `secure-handoff-folder`: publication instructions remain outside repo.
- `local-path-scrub`: public snapshot scrub before first push.', '2042d2c78505b6c6ca76808ec1b7c1a080fb2786e20d8313d2d25a5cba36e469', 56
);
