INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-28-techscope-quality-phase-5-test-layer-report#7', '2026-05-28-techscope-quality-phase-5-test-layer-report', 7, 'AM-CANDIDATE patterns',
  '## AM-CANDIDATE patterns

- `node-test-harness`: built-in Node test runner, no Jest/Vitest dependency.
- `frontmatter-fixtures`: small real Markdown fixtures for parser contracts.
- `scaffold-snapshot-tests`: frozen scaffold file-list snapshot for safe future
  Agents Mother refactors.
- `golden-checks-dry-run-contract`: machine-readable dry-run mode for testing
  test orchestration itself.', 'ae26a9c839b716a5fa84dd0d32e04df097a40aa5e4b46c27011017d9a65db95b', 59
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## AM-CANDIDATE patterns

- `node-test-harness`: built-in Node test runner, no Jest/Vitest dependency.
- `frontmatter-fixtures`: small real Markdown fixtures for parser contracts.
- `scaffold-snapshot-tests`: frozen scaffold file-list snapshot for safe future
  Agents Mother refactors.
- `golden-checks-dry-run-contract`: machine-readable dry-run mode for testing
  test orchestration itself.', 'AM-CANDIDATE patterns', '2026-05-28-techscope-quality-phase-5-test-layer-report', '2026-05-28-techscope-quality-phase-5-test-layer-report#7');

