INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-28-techscope-quality-phase-8-self-test-report#7', '2026-05-28-techscope-quality-phase-8-self-test-report', 7, 'AM-CANDIDATE patterns',
  '## AM-CANDIDATE patterns

- `self-test-mjs`: local operational pulse with baseline comparison.
- `queue-health-mjs`: read-only queue diagnostics with stale item reporting.
- `scheduled-health-pulse`: template-only candidate, not enabled by default.
- `proactive-self-test-contract`: explicit decision before any heartbeat or schedule.', '3a1ffd14477e45a759a6c29f36b67e3d6649894569d9ee7e33671766ce3d66ff', 50
);
