INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-28-techscope-quality-phase-9b-agents-mother-test-module-report#7', '2026-05-28-techscope-quality-phase-9b-agents-mother-test-module-report', 7, 'AM-CANDIDATE patterns',
  '## AM-CANDIDATE patterns

- `inspection-module`: project harness detection is reusable by test, handoff,
  operations, deployment and evolution flows.
- `no-report-test-mode`: diagnostic commands can be run in CI/gates without
  creating lifecycle artifacts.
- `shared-project-command-runner`: service/status/smoke commands share timeout,
  cwd and error-capture behavior.', '7d0f51ec2ffd909e8850db575fcf42ca894901b102ceffccc818393f557cc141', 56
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## AM-CANDIDATE patterns

- `inspection-module`: project harness detection is reusable by test, handoff,
  operations, deployment and evolution flows.
- `no-report-test-mode`: diagnostic commands can be run in CI/gates without
  creating lifecycle artifacts.
- `shared-project-command-runner`: service/status/smoke commands share timeout,
  cwd and error-capture behavior.', 'AM-CANDIDATE patterns', '2026-05-28-techscope-quality-phase-9b-agents-mother-test-module-report', '2026-05-28-techscope-quality-phase-9b-agents-mother-test-module-report#7');

