INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-29-fespa26-voice-control-and-feed-memory-update#9', '2026-05-29-fespa26-voice-control-and-feed-memory-update', 9, 'Reusable Standard Candidates',
  '## Reusable Standard Candidates

- `realtime-voice-control`: promote to active for Pritha descendants with voice plus complex tool workflows.
- `codex-task-transport`: define a standard task payload, status set, validation rule and fallback behavior for Codex App/CLI transports.
- `event-reportage-agent`: source intake, operational memory, reviewed feed cards and explicit publication gate.', '970f9bbe3ac5371cac076aea2ad76665336534f9de9df97fb37b70e9d4ae02ac', 67
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Reusable Standard Candidates

