INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-30-fespa26-voice-control-pattern-ingestion-report#3', '2026-05-30-fespa26-voice-control-pattern-ingestion-report', 3, 'Captured',
  '## Captured

- Reference implementation pack:
  `11_agents/reference-implementations/fespa26-voice-control/`.
- Source snapshot for Realtime session/call/tool routes, browser hook,
  instructions, tool schemas, Codex task service, Codex App/CLI/session
  adapters and relevant tests.
- Workflow:
  `07_workflows/realtime-voice-control-kit.md`.
- CLI surface:
  `node scripts/voice-control-kit.mjs`.
- Pritha alias:
  `node scripts/pritha.mjs voice-kit ...`.', '4dfe5f15ac35df9dc7220c714d779f84cdb076be30d0529a34827a6bf5597dfc', 59
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Captured

- Reference implementation pack:
